# AlphaPeptDeep — deep-learning predicted fragment intensity & RT prediction
# Supports HCD/CID (b/y ions) with instrument-specific & NCE-aware models.
_ALPHAPEPTDEEP_AVAILABLE = importlib.util.find_spec('peptdeep') is not None
_APD_ModelManager = None  # populated by _ensure_peptdeep()

def _ensure_peptdeep():
    """Import peptdeep on first use."""
    global _APD_ModelManager, _ALPHAPEPTDEEP_AVAILABLE
    if _APD_ModelManager is not None:
        return
    try:
        # Suppress the mask_modloss deprecation warning from peptdeep
        import warnings as _w
        _w.filterwarnings(
            'ignore',
            message='mask_modloss is deprecated',
        )
        # Snapshot root logger state before import; alphabase's set_logger()
        # may add/replace handlers, which can disconnect the GUI log widget.
        _root_logger = logging.getLogger()
        _pre_handlers = list(_root_logger.handlers)
        _pre_level = _root_logger.level
        _pre_disabled = _root_logger.disabled
        import peptdeep  # noqa: F811
        from peptdeep.pretrained_models import ModelManager as _MM
        
        # Prevent AlphaPeptDeep from automatically downloading default models during __init__
        import peptdeep.pretrained_models
        def _no_download(*args, **kwargs):
            raise RuntimeError("Model download suppressed.")
        peptdeep.pretrained_models.download_models = _no_download

        _orig_load_installed = _MM.load_installed_models
        def _safe_load_installed(self, *args, **kwargs):
            try:
                _orig_load_installed(self, *args, **kwargs)
            except Exception:
                pass # Suppress download/load errors during init, we load external models directly
        _MM.load_installed_models = _safe_load_installed

        # Remove any StreamHandler that alphabase silently added to root.
        for _h in list(_root_logger.handlers):
            if _h not in _pre_handlers and isinstance(_h, logging.StreamHandler) \
                    and not isinstance(_h, logging.FileHandler):
                _root_logger.removeHandler(_h)
        # If peptdeep replaced root handlers entirely, restore ours.
        for _h in _pre_handlers:
            if _h not in _root_logger.handlers:
                _root_logger.addHandler(_h)
        _root_logger.setLevel(_pre_level)
        _root_logger.disabled = _pre_disabled
        _APD_ModelManager = _MM
        _ALPHAPEPTDEEP_AVAILABLE = True
    except (ImportError, ModuleNotFoundError):
        _ALPHAPEPTDEEP_AVAILABLE = False

